-- Login links are generated by the app (auth.admin.generateLink) and mailed through Resend,
-- so the app rate-limits requests itself. Only keyed hashes of the email and IP are kept,
-- for one day. RLS is on with no policies: only the service role (server) can touch it.

create table login_link_requests (
  id bigint generated always as identity primary key,
  email_hash text not null,
  ip_hash text,
  created_at timestamptz not null default now()
);
create index login_link_requests_email_idx on login_link_requests (email_hash, created_at desc);
create index login_link_requests_ip_idx on login_link_requests (ip_hash, created_at desc);
alter table login_link_requests enable row level security;

-- 'ok' records the request; 'too_soon' = same email within 60 s; 'too_many' = 5/hour per email
-- or 20/hour per IP.
create or replace function claim_login_link(p_email_hash text, p_ip_hash text)
returns text
language plpgsql
security definer
set search_path = public
as $$
begin
  delete from login_link_requests where created_at < now() - interval '1 day';
  if exists (
    select 1 from login_link_requests
    where email_hash = p_email_hash and created_at > now() - interval '60 seconds'
  ) then
    return 'too_soon';
  end if;
  if (select count(*) from login_link_requests
      where email_hash = p_email_hash and created_at > now() - interval '1 hour') >= 5 then
    return 'too_many';
  end if;
  if p_ip_hash is not null and (select count(*) from login_link_requests
      where ip_hash = p_ip_hash and created_at > now() - interval '1 hour') >= 20 then
    return 'too_many';
  end if;
  insert into login_link_requests (email_hash, ip_hash) values (p_email_hash, p_ip_hash);
  return 'ok';
end;
$$;

revoke execute on function claim_login_link(text, text) from public, anon, authenticated;
